// Lee la caducidad real del certificado TLS y las Core Web Vitals de campo
// (CrUX, vía PageSpeed Insights) de una web, y las guarda en metrics_daily
// con upsert (site_id, day). Solo field data: si Google no tiene tráfico
// real de esta web, se guarda null en vez de una estimación de laboratorio.
//
// El sandbox del task runner no expone globals como URL: hay que pedirlos
// con require() igual que los módulos, y además añadirlos a
// NODE_FUNCTION_ALLOW_BUILTIN en n8n-task-runners.json ("crypto,tls,url").
const tls = require('tls');
const { URL } = require('url');

function getCertExpiry(hostname, port = 443, timeout = 8000) {
  return new Promise((resolve) => {
    let settled = false;
    const finish = (value) => {
      if (!settled) {
        settled = true;
        resolve(value);
      }
    };
    const socket = tls.connect(port, hostname, { servername: hostname, timeout }, () => {
      const cert = socket.getPeerCertificate();
      socket.end();
      finish(cert && cert.valid_to ? new Date(cert.valid_to).toISOString() : null);
    });
    socket.on('error', () => finish(null));
    socket.on('timeout', () => { socket.destroy(); finish(null); });
  });
}

const site = $input.item.json;
const hostname = new URL(site.url).hostname;

const sslExpiresAt = await getCertExpiry(hostname);

let lcpMs = null;
let inpMs = null;
let cls = null;

try {
  const psi = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://www.googleapis.com/pagespeedonline/v5/runPagespeed',
    qs: { url: site.url, strategy: 'mobile', key: $env.PAGESPEED_API_KEY },
    json: true,
    timeout: 30000,
    ignoreHttpStatusErrors: true,
    returnFullResponse: true,
  });
  const metrics = psi.body && psi.body.loadingExperience && psi.body.loadingExperience.metrics;
  if (metrics) {
    if (metrics.LARGEST_CONTENTFUL_PAINT_MS) lcpMs = metrics.LARGEST_CONTENTFUL_PAINT_MS.percentile;
    if (metrics.INTERACTION_TO_NEXT_PAINT) inpMs = metrics.INTERACTION_TO_NEXT_PAINT.percentile;
    if (metrics.CUMULATIVE_LAYOUT_SHIFT_SCORE) cls = metrics.CUMULATIVE_LAYOUT_SHIFT_SCORE.percentile / 100;
  }
} catch (err) {
  // Sin datos de PSI en esta ejecución: se queda en null, nunca un valor inventado.
}

const today = new Date().toISOString().slice(0, 10);

await this.helpers.httpRequest({
  method: 'POST',
  url: `${$env.SUPABASE_URL}/rest/v1/metrics_daily`,
  qs: { on_conflict: 'site_id,day' },
  headers: {
    apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
    Authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,
    'Content-Type': 'application/json',
    Prefer: 'resolution=merge-duplicates,return=minimal',
  },
  body: {
    site_id: site.id,
    day: today,
    ssl_expires_at: sslExpiresAt,
    lcp_ms: lcpMs,
    inp_ms: inpMs,
    cls,
  },
  json: true,
});

return {
  json: {
    site_id: site.id,
    site_name: site.name,
    site_url: site.url,
    ssl_expires_at: sslExpiresAt,
    lcp_ms: lcpMs,
    inp_ms: inpMs,
    cls,
  },
};

// Abre o cierra la incidencia informativa de "SSL a punto de caducar",
// mismo patrón que la incidencia de caída del recolector de uptime.
const SSL_EXPIRING_WARNING_DAYS = 14;

const item = $('Comprobar SSL y CWV').item.json;
const baseUrl = $env.SUPABASE_URL;
const headers = {
  apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
  Authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,
};

let action = 'none';
let message = null;

if (item.ssl_expires_at) {
  const daysLeft = Math.floor((new Date(item.ssl_expires_at).getTime() - Date.now()) / 86400000);

  const openIncidents = await this.helpers.httpRequest({
    method: 'GET',
    url: `${baseUrl}/rest/v1/incidents`,
    qs: {
      site_id: `eq.${item.site_id}`,
      kind: 'eq.ssl_expiring',
      resolved_at: 'is.null',
      select: 'id,opened_at',
      order: 'opened_at.desc',
      limit: '1',
    },
    headers,
    json: true,
  });
  const openIncident = openIncidents[0] ?? null;

  if (daysLeft <= SSL_EXPIRING_WARNING_DAYS && !openIncident) {
    await this.helpers.httpRequest({
      method: 'POST',
      url: `${baseUrl}/rest/v1/incidents`,
      headers: { ...headers, 'Content-Type': 'application/json', Prefer: 'return=minimal' },
      body: {
        site_id: item.site_id,
        kind: 'ssl_expiring',
        severity: 'info',
        detail: `Caduca el ${item.ssl_expires_at}`,
      },
      json: true,
    });
    action = 'opened';
    message = `⚠️ El SSL de ${item.site_name} caduca en ${daysLeft} días.\n${item.site_url}`;
  } else if (daysLeft > SSL_EXPIRING_WARNING_DAYS && openIncident) {
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: `${baseUrl}/rest/v1/incidents`,
      qs: { id: `eq.${openIncident.id}` },
      headers: { ...headers, 'Content-Type': 'application/json', Prefer: 'return=minimal' },
      body: { resolved_at: new Date().toISOString() },
      json: true,
    });
    action = 'closed';
    message = `✅ El SSL de ${item.site_name} se ha renovado.\n${item.site_url}`;
  }
}

return { json: { action, message } };
